import { RendererCanvas, Vector3, remap, getImgFromURL } from '../../../../lib';

const PARAM = undefined;

export class Solution {
	public divHost: HTMLElement;
	public renderer: Renderer;
	constructor(id: string) {
		this.divHost = document.getElementById(id) as HTMLDivElement;
		const div = document.createElement('div');

		this.divHost.appendChild(div);

		// TODO
		// You code goes here for one time operation

		this.renderer = new Renderer(div);

		// !! you should execute it for rendering
		// this.start();
	}
	public destroy() {
		this.renderer.destroy();
		try {
			while (this.divHost && this.divHost.lastElementChild) {
				const lastChild = this.divHost.lastElementChild as Node;
				this.divHost.removeChild(lastChild);
			}
		} catch (error) {
			console.error('Error removing child elements:', error);
		}
	}
}

export class Renderer extends RendererCanvas {
	accList: number[] = [];
	lossList: number[] = [];
	img: HTMLImageElement;
	loadingDiv: HTMLDivElement;
	divOutput: HTMLDivElement;
	// url: string = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/person/HaminHaram.jpg';
	url: string = 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTlfPtPb33NScAJV_mYnqcvYHYw19OTcTmEGA&s';
	constructor(divHost: HTMLDivElement) {
		super(divHost);
		// TODO
		// You code goes here for one time operation
		this.init();
	}
	async init() {
		if (PARAM?.url) {
			this.loadImg(PARAM?.url);
		} else {
			this.loadImg();
		}

		this.img = new Image();
		this.divHost.append(this.img);

		const urlDiv = document.createElement('input')!;
		urlDiv.style.width = '500px';
		urlDiv.style.height = '20px';
		urlDiv.textContent = 'execute';
		urlDiv.value = this.url;
		urlDiv.placeholder = 'URL';
		urlDiv.contentEditable = 'true';
		this.divHost.append(urlDiv);

		const btn = document.createElement('button')!;
		btn.style.width = '100px';
		btn.style.height = '20px';
		btn.textContent = 'execute';
		this.divHost.append(btn);

		const output = document.createElement('div')!;
		this.divOutput = output;
		this.divHost.append(output);

		btn.addEventListener('click', async () => {
			const imageUrl = urlDiv.value;
			this.appendLoading();
			this.divOutput.innerHTML = '';
			const url = `http://127.0.0.1:8000/api/v1/imgSegLLM?image_url=${imageUrl}`;
			// const url = `http://127.0.0.1:8000/api/v1/imgSegLLM?image_url=${encodeURIComponent(imageUrl)}`;
			// console.log(url);
			btn.disabled = true;
			try {
				const res = await fetch(url);
				const dataString = await res.json();

				const dataJson = toJSON(dataString);
				// console.log(dataJson);

				output.textContent = JSON.stringify(dataString, null, 2);
				btn.disabled = false;
				this.divHost.removeChild(this.loadingDiv);
				this.loadImg(imageUrl);
				this.updateResult(dataJson);
			} catch (err) {
				output.textContent = 'Error: ' + String(err);
			}
		});

		this.updateResult(toJSON(dummyReresult));

		this.isStatic = true;
	}
	public appendLoading(): void {
		const loadingDiv = document.createElement('div');
		loadingDiv.id = 'loading';
		Object.assign(loadingDiv.style, {
			position: 'absolute',
			top: '50%',
			left: '50%',
			transform: 'translate(-50%, -50%)',
			zIndex: '9999',
			backgroundColor: 'rgba(255, 255, 255, 0.5)',
			padding: '10px',
			borderRadius: '8px',
		});

		const path = 'https://raw.githubusercontent.com/NamjuLee/data/master/map/loading.gif';
		const loadingImg = document.createElement('img');
		Object.assign(loadingImg, {
			src: path,
			style: { backgroundColor: 'transparent' },
			alt: 'Loading...',
			width: 120,
		});

		loadingDiv.appendChild(loadingImg);
		this.loadingDiv = loadingDiv;
		this.divHost.appendChild(loadingDiv);
	}
	// // http://localhost:9999/njs-lab-public/lab/machine-learning/tf-image-seg?url=https://raw.githubusercontent.com/NamjuLee/data/master/img/person/Haram_small.jpg

	public async loadImg(path = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/bg/zoom-James-River-Kayaking.jpg') {
		getImgFromURL(path).then((img: HTMLImageElement | void) => {
			if (!img) return;
			this.img.src = img.src;
		});
		this.isStatic = true;
	}

	public updateResult(parsed) {
		let html = '';

		// Summary
		html += `
			<div class="summary">
			<h2>Summary</h2>
			<p>${parsed.image_analysis_summary}</p>
			<p><b>Total Segments:</b> ${parsed.total_segments_identified}</p>
			</div>
		`;

		// Segments
		html += `<h2>Segments</h2>`;
		parsed.segment_analysis.forEach((seg: any) => {
			html += `
			<div class="segment-card">
				<div><span class="label">#${seg.segment_index}</span> — ${seg.segment_class_label}</div>
				<div><b>Pixels:</b> ${seg.pixel_percentage}%</div>
				<div>${seg.contextual_description}</div>
			</div>
			`;
		});

		this.divOutput.innerHTML = html;
	}
}

const toJSON = (rawData) => {
	const match = rawData.result.match(/```json[\s\S]*?```/);
	const cleanJson = match[0].replace('```json', '').replace('```', '').trim();
	const parsed = JSON.parse(cleanJson);
	return parsed;
};

